"use client";
import {Icon,External} from "./hub-ui";
export default function SettingsView({theme,setTheme,auto,setAuto,refresh,busy,errors}:{theme:string;setTheme:(v:string)=>void;auto:boolean;setAuto:(v:boolean)=>void;refresh:()=>void;busy:boolean;errors:number}){
return <div className="settings-grid"><section className="panel"><h2>Appearance</h2><p className="muted">Two looks, same hub. Your choice is saved on this device.</p><div className="theme-choices"><button className={theme==="cream"?"chosen":""} onClick={()=>setTheme("cream")}><Icon name="sun"/><b>Atelier Cream</b><small>Warm paper, big serif type, bronze accents</small></button><button className={theme==="chrome"?"chosen":""} onClick={()=>setTheme("chrome")}><Icon name="moon"/><b>Midnight Chrome</b><small>True black with silver chrome accents</small></button></div></section><section className="panel"><h2>GitHub status</h2><p className="muted">Read-only tracking; no repository changes.</p><div className="setting-row"><span>Source</span><b>{errors?"Partial access":"Read-only"}</b></div><div className="setting-row"><span>Auto-refresh every 2 minutes</span><button className={"switch "+(auto?"on":"")} role="switch" aria-checked={auto} onClick={()=>{setAuto(!auto);localStorage.setItem("nbo-auto",auto?"off":"on")}}><span/></button></div><button className="btn secondary" disabled={busy} onClick={refresh}><Icon name="refresh"/> Refresh</button></section><section className="panel"><h2>Local preferences</h2><p className="muted">Custom prompts and checklist progress are stored on this device.</p><button className="btn secondary" onClick={()=>{localStorage.removeItem("nbo-checks");window.dispatchEvent(new Event("nbo-reset"))}}>Reset checklist progress</button></section><section className="panel"><h2>Security and account</h2><p className="muted">Only GitHub information is displayed. Files and personal notes stay on this device.</p><External className="btn secondary" href="https://github.com/ejnburrows-rgb/Command-Center-">Hub repository</External></section></div>;
}
