import type {ReactNode} from "react";
export function Icon({name}:{name:string}){return <span aria-hidden="true" className="glyph">{({Home:"⌂",Hub:"⌂",Graph:"◎",Projects:"▦",Library:"▤","Best Practices":"▤",Prompts:"◫",Tools:"⚙",Assets:"▧",Settings:"⚙",gear:"⚙",search:"⌕",refresh:"↻",sun:"☼",moon:"☾",arrow:"→",back:"←",copy:"▣",plus:"+",github:"◈",close:"×",menu:"☰",check:"✓",logout:"↪"} as Record<string,string>)[name]||"◈"}</span>}
export function External({href,children,className=""}:{href:string;children:ReactNode;className?:string}){return <a href={href} target="_blank" rel="noopener noreferrer" className={className}>{children}<span aria-hidden="true">↗</span></a>}
export function Stat({label,value}:{label:string;value:string|number}){return <div className="stat"><small>{label}</small><strong>{value}</strong></div>}
